"""Generate a base-2^29 Montgomery multiply with a final 24-bit reduction."""
from pathlib import Path

root = Path(__file__).resolve().parents[1] / "shaders"
p = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
radix = 1 << 29
mask = radix - 1
words = [(p >> (29 * i)) & mask for i in range(9)]
inverse = -pow(p, -1, radix) % radix
source = [
    '// Generated by tools/gen_metal_radix29.py.',
    'struct fp29 { uint v[9]; };',
    'constant uint FP29_MASK = 0x1fffffffu;',
    'constant uint FP29_Q[9] = {' + ', '.join(hex(word) + 'u' for word in words) + '};',
    f'constant uint FP29_INV = {hex(inverse)}u;',
    '',
    'inline fp29 fp29_pack(fp_t a) {',
    '  fp29 r;',
]
for i in range(9):
    word, shift = divmod(i * 29, 32)
    expr = f'(a.v[{word}] >> {shift})'
    if shift + 29 > 32 and word + 1 < 8:
        expr += f' | (a.v[{word + 1}] << {32 - shift})'
    source.append(f'  r.v[{i}] = ({expr}) & FP29_MASK;')
source += ['  return r;', '}', '', 'inline fp_t fp29_unpack(fp29 a) {', '  fp_t r;']
for i in range(8):
    word, shift = divmod(i * 32, 29)
    expr = f'(a.v[{word}] >> {shift})'
    for j in range(1, 3):
        distance = j * 29 - shift
        if distance < 32 and word + j < 9:
            expr += f' | (a.v[{word + j}] << {distance})'
    source.append(f'  r.v[{i}] = {expr};')
source += [
    '  return r;', '}', '',
    'inline fp29 fp29_reduce(fp29 a) {',
    '  fp29 d;',
    '  int borrow = 0;',
    '#pragma clang loop unroll(full)',
    '  for (uint i = 0; i < 9; i++) {',
    '    const int v = int(a.v[i]) - int(FP29_Q[i]) - borrow;',
    '    d.v[i] = uint(v) & FP29_MASK;',
    '    borrow = int(v < 0);',
    '  }',
    '  return borrow == 0 ? d : a;',
    '}', '',
    'template <bool Square = false>',
    'inline fp29 fp29_mul(fp29 a, fp29 b) {',
    '  ulong carry = 0;',
]
for i in range(17):
    # At most 18 products, including Montgomery correction, fit in 63 bits.
    lo, hi = max(0, i-8), min(8, i)
    source.append('  {')
    source.extend(['    ulong ab = 0;', '    ulong mq = 0;', '    if (Square) {'])
    for j in range(lo, i//2+1):
        product = f'(ulong)a.v[{j}] * a.v[{i-j}]'
        if j != i-j:
            product = f'({product}) << 1'
        source.append(f'      ab += {product};')
    source.append('    } else {')
    for j in range(lo, hi+1):
        source.append(f'      ab += (ulong)a.v[{j}] * b.v[{i-j}];')
    source.append('    }')
    for j in range(lo, min(8, i-1)+1):
        source.append(f'    mq += (ulong)m{j} * FP29_Q[{i-j}];')
    source.extend(['    carry += ab + mq;', '  }'])
    if i < 9:
        m = 'FP29_MASK' if i != 8 else '0x00ffffffu'
        source.extend([f'  const uint m{i} = (uint(carry) * FP29_INV) & {m};',
                       f'  carry += (ulong)m{i} * FP29_Q[0];'])
    if i >= 8:
        source.append(f'  const uint t{i} = uint(carry) & FP29_MASK;')
    source.append('  carry >>= 29;')
source += ['  const uint t17 = uint(carry);', '  fp29 r;']
for i in range(9):
    source.append(f'  r.v[{i}] = ((t{i+8} >> 24) | (t{i+9} << 5)) & FP29_MASK;')
source += ['  return fp29_reduce(r);', '}']
(root / 'radix29.metal').write_text('\n'.join(source)+'\n')
